import{_ as t,o,c as s,a2 as n}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/troubleshooting.md","filePath":"user-guide/troubleshooting.md","lastUpdated":1785993908000}'),r={name:"user-guide/troubleshooting.md"};function i(a,e,l,h,d,u){return o(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="the-global-hotkey-doesn-t-respond" tabindex="-1">The global hotkey doesn&#39;t respond <a class="header-anchor" href="#the-global-hotkey-doesn-t-respond" aria-label="Permalink to &quot;The global hotkey doesn&#39;t respond&quot;">​</a></h2><ol><li>Check <strong>Settings → Service Status</strong> — if the background service isn&#39;t running, reinstalling or restarting it from that page usually fixes indexing-related issues, but the toggle hotkey itself is handled by the App process, not the service, so this is a secondary check.</li><li>If the foreground app is running elevated (as administrator) and Lertaro isn&#39;t, Windows blocks lower-privilege processes from sending it input. Lertaro&#39;s background hotkey-listener process is elevated automatically whenever your account is an administrator — no setting to enable, no UAC prompt. If hotkeys still don&#39;t reach an elevated window, check <strong><a href="./settings/service-status.html">Settings → Service Status</a></strong> to confirm the background service is running, since it&#39;s what launches the elevated listener. If your account isn&#39;t an administrator, there&#39;s no workaround — Windows won&#39;t let a lower-privilege process signal a higher-privilege one.</li><li>Check the <strong><a href="./settings/hotkeys-page.html#process-blacklist">Process Blacklist</a></strong> — if the foreground app&#39;s executable name was added there (intentionally or by accident), Lertaro&#39;s global hotkeys are deliberately let through untouched while it&#39;s focused.</li><li>If the foreground app is genuinely full-screen (fills the entire monitor), Lertaro automatically lets its hotkeys through too by default — so it doesn&#39;t fight with fullscreen games. If your configured combo won&#39;t collide with anything the fullscreen app itself uses, enable <strong>Still respond while a fullscreen app is focused</strong> next to <strong>Settings → Hotkeys → Show/Hide Quick Search</strong> to keep it working there too. Otherwise, alt-tabbing out, or running the app in borderless/windowed mode instead of exclusive full-screen, avoids it.</li></ol><h2 id="search-results-seem-out-of-date" tabindex="-1">Search results seem out of date <a class="header-anchor" href="#search-results-seem-out-of-date" aria-label="Permalink to &quot;Search results seem out of date&quot;">​</a></h2><p>NTFS and ReFS drives update from the USN Journal in near real time; other local file systems (FAT32, exFAT, ...) are watched for changes directly instead, just as continuously. If something still looks stale (a file you just created isn&#39;t showing up, or a deleted file still appears), use <strong>Rebuild Index</strong> on the affected drive under <strong>Settings → Index → Local Drives</strong> (or <strong>Network Drives</strong>).</p><h2 id="a-network-drive-never-seems-to-refresh" tabindex="-1">A network drive never seems to refresh <a class="header-anchor" href="#a-network-drive-never-seems-to-refresh" aria-label="Permalink to &quot;A network drive never seems to refresh&quot;">​</a></h2><p>Network shares don&#39;t have a USN Journal Lertaro can watch, so they&#39;re re-scanned on a schedule instead. Check the drive&#39;s <strong>Refresh Mode</strong> under <strong>Settings → Index → Network Drives</strong> — if it&#39;s set to <strong>Manual</strong>, nothing updates automatically; switch it to a timed interval, or use <strong>Rebuild Index</strong> to refresh on demand. For NAS SMB shares with special symlinks or recursive folder loops, the scan engine includes built-in loop detection to prevent duplicate entries and recursion blips.</p><h2 id="the-preview-window-looks-wrong-cut-off" tabindex="-1">The preview window looks wrong / cut off <a class="header-anchor" href="#the-preview-window-looks-wrong-cut-off" aria-label="Permalink to &quot;The preview window looks wrong / cut off&quot;">​</a></h2><p>This shouldn&#39;t happen — Lertaro clamps the QuickLook preview window&#39;s position and size to your monitor&#39;s usable area automatically. If you still see clipping, try <strong>Settings → General → Preview → Reset Preview Window Settings</strong> to rule out an unusual manual width/height value, and make sure you&#39;re on the latest release.</p><h2 id="a-file-folder-doesn-t-show-up-at-all" tabindex="-1">A file/folder doesn&#39;t show up at all <a class="header-anchor" href="#a-file-folder-doesn-t-show-up-at-all" aria-label="Permalink to &quot;A file/folder doesn&#39;t show up at all&quot;">​</a></h2><ul><li>Check it isn&#39;t excluded — <strong>Settings → Index → Exclusion Rules</strong> supports exact paths, glob patterns, and regexes, and any of the three could be catching it unintentionally.</li><li>Check the drive it lives on is enabled under <strong>Settings → Index → Local/Network Drives</strong>.</li></ul><h2 id="typing-chinese-or-another-ime-language-into-the-inline-window-doesn-t-work" tabindex="-1">Typing Chinese (or another IME language) into the inline window doesn&#39;t work <a class="header-anchor" href="#typing-chinese-or-another-ime-language-into-the-inline-window-doesn-t-work" aria-label="Permalink to &quot;Typing Chinese (or another IME language) into the inline window doesn&#39;t work&quot;">​</a></h2><p>The <a href="./getting-started.html#the-three-windows">inline window</a> deliberately never takes real keyboard focus away from the window it&#39;s docked in — that&#39;s what lets you dismiss it and land exactly back where you were, with no focus flicker. An IME&#39;s composition (the candidate list, and the character it actually commits) only happens for whichever window holds <em>real</em> focus, though, which is always the docked-in app, never Lertaro — so there&#39;s no message Lertaro could intercept to capture what you typed. This is a structural limitation of how the inline window works, not a bug.</p><p>Two options:</p><ul><li>Type the pinyin romanization directly (no IME candidate popup needed) — Lertaro matches Chinese filenames by pinyin automatically, see <a href="./search-syntax.html#chinese-filenames-pinyin-aliasing">Search Syntax</a>.</li><li>Use the <a href="./getting-started.html#the-three-windows">quick window</a> instead (double-tap <code>Ctrl</code> by default) — it&#39;s a real focused window, so IME composition works there normally.</li></ul><h2 id="still-stuck" tabindex="-1">Still stuck? <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck?&quot;">​</a></h2><p>Check the <strong>Service</strong>, <strong>App</strong>, and <strong>Hook</strong> log tabs under <strong><a href="./settings/service-status.html">Settings → Service Status</a></strong> — the search box there filters by keyword, and the level dropdown filters by severity — before filing an issue on GitHub.</p>',17)])])}const p=t(r,[["render",i]]);export{g as __pageData,p as default};
